{
  "responses": [
    {
      "tone": "objetivo",
      "text": "Claro, vou verificar a disponibilidade para enviar o cronograma atualizado hoje. Aguarde um retorno.",
      "probability": 0.35
    },
    {
      "tone": "cordial",
      "text": "Com certeza! Farei o meu melhor para enviar a versão atualizada do cronograma ainda hoje.",
      "probability": 0.28
    },
    {
      "tone": "empatico",
      "text": "Entendo a urgência. Vou priorizar e garantir que você receba o cronograma atualizado hoje mesmo.",
      "probability": 0.25
    },
    {
      "tone": "direto",
      "text": "Consigo enviar a atualização do cronograma hoje. Confirme o canal de envio, por favor.",
      "probability": 0.18
    },
    {
      "tone": "animado",
      "text": "Pode deixar! Vou correr para atualizar e enviar o cronograma rapidinho, sem problemas!",
      "probability": 0.15
    }
  ]
}
```

